<script setup>
import { ref, onMounted } from "vue";
import { store } from "../../store.js";
import { useWindowSize } from "@vueuse/core";

const { width } = useWindowSize();

import debounce from "lodash/debounce";

const debouncedSearch = debounce(() => store.fetchSearchResults(), 250);

// add some event listeners when the page loads.
onMounted(() => {
  const mySects = document.getElementsByClassName("sect");

  for (const s of mySects) {
    s.addEventListener("mouseenter", () => {
      s.setAttribute("fill-opacity", "0.6");
    });

    s.addEventListener("mouseleave", () => {
      s.setAttribute("fill-opacity", "0.02");
    });

    s.addEventListener("click", () => {
      if (width.value < 1050) {
        store.fetchSearchResults();
        store.displayStepTwoOverlay = true;
        return;
      }

      debouncedSearch();
    });
  }
});

const showFrontView = ref(true);
const showBackView = ref(false);

function switchViews() {
  showFrontView.value = !showFrontView.value;
  showBackView.value = !showBackView.value;
}
</script>

